(27, 'Contact Us', NULL, '<p>Phone Number: 9135672390</p>\n', 3, NULL, '', '', '', NULL, 1, NULL, NULL, '2021-05-27 10:33:40', '2021-05-27 10:35:54', 'contact-us'),
(29, 'Competition Laws', NULL, '<p>We follow the competition laws as reinforced by the Indian Competition Act 2002</p>\n', 5, NULL, 'Competition Law', 'Competition Law Compliance ', 'Competition Law', NULL, 1, NULL, NULL, '2021-07-23 08:26:31', NULL, 'competition-law'),
(30, 'Cyber Law Due Diligence', NULL, '<p>Cybersecurity due diligence is&nbsp;<strong>a process by which we can identify and remediate the cyber risks of third-party</strong>. ... During the process of due diligence, organisations collect insights of the 3rd party&#39;s existing efforts for the protection of their data.</p>\n', 5, NULL, 'Cyber Law Due Diligence', 'Cyber Law Due Diligence', 'Cyber Law Due Diligence', NULL, 1, NULL, NULL, '2021-07-23 08:28:04', NULL, 'cyber-law-due-diligence'),
(31, 'Data Protection', NULL, '<p>We follow all the data protection policies&nbsp;</p>\n', 5, NULL, 'Data Protection', 'Data Protection', 'Data Protection', NULL, 1, NULL, NULL, '2021-07-23 08:28:50', NULL, 'data-protection'),
(32, 'Certificate of Commencement', NULL, '<p>Certificate of Commencement</p>\n', 5, NULL, 'Certificate of Commencement', 'Certificate of Commencement', 'Certificate of Commencement', NULL, 1, NULL, NULL, '2021-07-23 08:29:56', NULL, 'certificate-of-commencement'),
(33, 'Sell on Spurtcart', NULL, '&lt;p&gt;Sell on Spurtcart&lt;/p&gt;\n', 6, NULL, 'Sell on Spurtcart', 'Sell on Spurtcart', 'Sell on Spurtcart', NULL, 1, NULL, NULL, '2021-07-23 08:55:11', '2023-02-03 05:17:26', 'sell-on-spurtcart'),
(34, 'Affiliates', NULL, '<p>Affiliates</p>\n', 6, NULL, 'Affiliates', 'Affiliates', 'Affiliates', NULL, 1, NULL, NULL, '2021-07-23 08:55:46', NULL, 'affiliates'),
(35, 'demo pages', NULL, '&lt;p&gt;demo pages&lt;/p&gt;\n', 5, NULL, 'demo pages', 'demo pages', 'demo pages', NULL, 1, NULL, NULL, '2021-07-28 05:05:00', '2023-02-03 05:17:10', 'demo-pages'),
(36, 'Brand', NULL, '&lt;p&gt;A&amp;nbsp;&lt;em&gt;brand&lt;/em&gt;&amp;nbsp;is a name&sbquo; term&sbquo; design&sbquo; symbol or any other feature that distinguishes one seller&amp;&#35;39;s good or service from those of other sellers. &amp;middot;&lt;/p&gt;\n', 7, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, '2022-12-06 12:48:03', NULL, 'brand'),
