(897, 'EL001', '2132', 500, 4, NULL, NULL, 81, 0, '250.00', '2021-05-22', 1, 'PHI Learning Data Communications And Computer Networks', '<table>\n	<tbody>\n		<tr>\n			<td>\n			<ul>\n				<li>PHI Learning</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Title</td>\n			<td>\n			<ul>\n				<li>Data Communications And Computer Networks by Prakash C. Gupta</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Type</td>\n			<td>\n			<ul>\n				<li>Higher Education</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Language</td>\n			<td>\n			<ul>\n				<li>English</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Format</td>\n			<td>\n			<ul>\n				<li>Voucher</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Benefits</td>\n			<td>\n			<ul>\n				<li>Online access</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Publication Year</td>\n			<td>\n			<ul>\n				<li>2014</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Duration</td>\n			<td>\n			<ul>\n				<li>5 Year</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Exam Type</td>\n			<td>\n			<ul>\n				<li>NA</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Description</td>\n			<td>\n			<ul>\n				<li>The book gives a masterly analysis of topics ranging from the principles of data transmission to computer networking applications. It also provides standard protocols, thereby enabling to bridge the gap between theory and practice. Whats more, it correlates the network protocols to the concepts, which are explained with the help of numerous examples to facilitate students understanding of the subject.</li>\n			</ul>\n			</td>\n		</tr>\n	</tbody>\n</table>\n\n<p>School Course Material</p>\n\n<table>\n	<tbody>\n		<tr>\n			<td>Board Type</td>\n			<td>\n			<ul>\n				<li>NA</li>\n			</ul>\n			</td>\n		</tr>\n		<tr>\n			<td>Class/Grade</td>\n			<td>\n			<ul>\n				<li>NA</li>\n			</ul>\n			</td>\n		</tr>\n	</tbody>\n</table>\n', NULL, 'e lEARNING', 'e lEARNING', 'e lEARNING', NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, 0, 1, 80, NULL, '2021-05-22 15:26:10', '2022-11-08 08:43:40', '~E-Learning~,~Books~,~Sports, Books and More~,~PHI Learning Data Communications And Computer Networks~', NULL, 'phi-learning-data-communications-and-computer-networks', '{\"productCost\":250,\"packingCost\":0,\"shippingCost\":0,\"tax\":0,\"others\":0}', 1, 0, NULL, '0.00', '0.00', '0.00', '0.00', 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 657, 1, '133', '', 0, 1, 0, NULL),
(898, 'SKU7445678', '3454', 55, 4, NULL, NULL, 82, 0, '898.00', '2021-05-22', 2, 'Neeman Cotton Classic Sneakers for Men', '<ul>\n	<li>Closure: Lace-Up</li>\n	<li>Heel Height: 7 centimeters</li>\n	<li>Shoe Width: Medium</li>\n	<li>One of its kind Sneakers , designed for All-Day and All Seasons wear. India&rsquo;s first shoes made with Organic Cotton, Recycled Fabrics, lined with Merino Wool and moulded with a super lightweight Natural Rubber sole.</li>\n	<li>Proprietary diamond pattern gives it the precise grip, making it suitable for day-to-day wear. Perfect combination of classic style and superior comfort.</li>\n	<li>Insole: Made of Recycled rubber + castor bean seed oil + fine quality Merino Wool lining; Outsoles : 100% Slip-resistant Natural Rubber</li>\n	<li>Breathable : Wear Sock-free and Stay Odour-free; Comfortable, Sustainable and Eco-friendly shoe.</li>\n	<li>Ideal for Summers and suitable for 12 to 14 hours in a day. Easy maintenance: Machine washable or Hand Wash.</li>\n</ul>\n', NULL, '', '', '', NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, 0, 1, 80, NULL, '2021-05-22 15:49:55', '2022-11-08 08:43:40', '~Sneakers~,~Neeman Cotton Classic Sneakers for Men~', NULL, 'neeman-cotton-classic-sneakers-for-men', '{\"productCost\":898,\"packingCost\":0,\"shippingCost\":0,\"tax\":0,\"others\":0}', 1, 0, NULL, '0.00', '0.00', '0.00', '0.00', 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 658, 1, '3454', '', 0, 1, 0, NULL),
