(1801, 'SKU7346538467534', '456434', 100, 4, NULL, NULL, 96, 1, '500.00', '2022-01-28', 100, 'Apple iPhone 12 (128GB) - Green', '<ul>\n	<li>6.1-inch (15.5 cm diagonal) Super Retina XDR display</li>\n	<li>Ceramic Shield, tougher than any smartphone glass</li>\n	<li>A14 Bionic chip, the fastest chip ever in a smartphone</li>\n	<li>Advanced dual-camera system with 12MP Ultra Wide and Wide cameras; Night mode, Deep Fusion, Smart HDR 3, 4K Dolby Vision HDR recording</li>\n	<li>12MP TrueDepth front camera with Night mode, 4K Dolby Vision HDR recording</li>\n	<li>Industry-leading IP68 water resistance</li>\n	<li>Supports MagSafe accessories for easy attach and faster wireless charging</li>\n	<li>iOS with redesigned widgets on the Home screen, all-new App Library, App Clips and more</li>\n</ul>\n', NULL, 'Apple iPhone 12 (128GB) - Green', '', '', NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, 0, 1, 175, NULL, '2022-01-28 06:53:40', '2022-11-08 08:44:45', '~I Phone~,~Apple iPhone 12 (128GB) - Green~', NULL, 'apple-iphone-12-128gb---green', '{\"productCost\":500,\"packingCost\":0,\"shippingCost\":0,\"tax\":0,\"others\":0}', 2, 13, NULL, '0.00', '0.00', '0.00', '0.00', 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 3513, 1, '56545', '', 0, 2, 0, NULL),
(1802, 'SKU74356345786', '4574567', 100, 1, NULL, NULL, 63, 0, '20000.00', '2022-01-28', 0, 'OnePlus 9R 5G', '<ul>\n	<li>Qualcomm Snapdragon 870 5G with upgraded Qualcomm Kryo 585 CPU that performs intense mobile computing at up to 3.2 GHz and also comes with an ultra-fast Qualcomm Adreno 650 GPU for superb on-device experiences</li>\n	<li>Loaded with Quad rear camera module that features a 48 MP Main camera, 16 MP Ultra Wide angle Camera, 5 MP Macro camera and a 2 MP Monochrome camera. The device also comes with a 16 MP front Camera</li>\n	<li>6.55 Inches Fluid AMOLED display with 120 Hz of Refresh rate</li>\n	<li>A Powerful 4500 mAh with 65 Watt Warp charging capability</li>\n	<li>Oxygen OS based on Andriod 11</li>\n	<li>Hands-Free access to Alexa: Alexa on your phone lets you make phone calls, open apps, control smart home devices, access the library of Alexa skills, and more using just your voice while on-the-go. Download the Alexa app and complete hands-free setup to get started. Just ask - and Alexa will respond instantly</li>\n</ul>\n', NULL, 'OnePlus 9R 5G', 'OnePlus 9R 5G', 'OnePlus 9R 5G', NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, 0, 1, 175, NULL, '2022-01-28 09:10:31', '2023-07-21 07:27:47', '~I Phone~,~OnePlus 9R 5G~', NULL, 'oneplus-9r-5g', '{\"productCost\":20000,\"packingCost\":0,\"shippingCost\":0,\"tax\":0,\"others\":0}', 1, 0, NULL, '0.00', '0.00', '0.00', '0.00', 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 3514, 0, '4574567', '~Display Type- Full HD+ AMOLED Display~,~Operating System- Android 11~', 0, 2, 0, NULL);
